fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    for (i, &value) in nums.iter().enumerate() {
        if value == target {
            // Found the target at index `i`
            return i as i32;
        }
    }
    // Target not found
    -1
}

fn main() {
    let nums = vec![3, 5, 7, 5, 9];
    assert_eq!(linear_search(nums.clone(), 5), 1);  // first occurrence of 5 is at index 1
    assert_eq!(linear_search(nums.clone(), 9), 4);
    assert_eq!(linear_search(nums.clone(), 2), -1); // 2 is not in the list
    println!("All tests passed!");
}